Fill Missing Values - Advanced Technique

get_mode &lt;- function(x) {
  ux &lt;- stats::na.omit(object = base::unique(x = x))
  ux[base::which.max(x = base::tabulate(bin = base::match(x = x, table = ux)))]
}
datasets::penguins %&gt;%
  dplyr::mutate(
    dplyr::across(
      .cols = dplyr::where(fn = is.numeric),
      .fns = function(.col) {
        dplyr::if_else(
          condition = base::is.na(x = .col),
          true = stats::median(x = .col, na.rm = TRUE),
          false = .col
        )
      }
    ),
    dplyr::across(
      .cols = dplyr::where(fn = function(.col) {
        !is.numeric(x = .col)
      }),
      .fns = function(.col) {
        dplyr::if_else(
          condition = base::is.na(x = .col),
          true = get_mode(x = .col),
          false = .col
        )
      }
    )
  ) %&gt;%
  dplyr::summarise(
    dplyr::across(
      .cols = everything(vars = .),
      .fns = function(.col) {
        base::sum(!base::is.na(x = .col))
      },
      .names = "n_{.col}"
    )
  )


